-- AutoTyper PT / EN / ES (painel parecido com o do vídeo)
-- Palavra sugerida + botão ESCREVER + velocidade Lento/Rápido em ms
-- Suggested word + WRITE button + Slow/Fast speed in ms
-- Palabra sugerida + botón ESCRIBIR + velocidad Lento/Rápido en ms

local sucesso, erro = pcall(function()
    local Players = game:GetService("Players")
    local jogador = Players.LocalPlayer
    local playerGui = jogador:WaitForChild("PlayerGui")
    local okVIM, VIM = pcall(function() return game:GetService("VirtualInputManager") end)
    local UIS = game:GetService("UserInputService")
    local GuiService = game:GetService("GuiService")
    -- Se o script for executado de novo, só a cópia mais nova continua viva (as antigas param os loops).
    -- Duas cópias ao mesmo tempo digitavam em dobro, repetiam palavras e travavam o jogo.
    local genv = (getgenv and getgenv()) or _G
    genv.AutoTyperToken = (genv.AutoTyperToken or 0) + 1
    local meuToken = genv.AutoTyperToken

    -- Registro vivo dos textos da tela: em vez de varrer o PlayerGui inteiro toda hora (GetDescendants cria uma
    -- lista gigante a cada chamada, e isso faz o jogo travar), o script mantém uma lista que se atualiza sozinha.
    local textLabels = {}
    local function registrarTexto(obj)
        if obj:IsA("TextLabel") then textLabels[obj] = true end
    end
    for _, obj in ipairs(playerGui:GetDescendants()) do registrarTexto(obj) end
    local conAdd, conRem
    conAdd = playerGui.DescendantAdded:Connect(function(obj)
        if genv.AutoTyperToken ~= meuToken then -- cópia antiga: solta as conexões
            conAdd:Disconnect()
            if conRem then conRem:Disconnect() end
            return
        end
        registrarTexto(obj)
    end)
    conRem = playerGui.DescendantRemoving:Connect(function(obj) textLabels[obj] = nil end)
    local ultimoScanWorkspace = 0 -- varrer o workspace inteiro pesa muito: no máximo uma vez a cada 4 s

    ---------------------------------------------------------------- config
    local config = {
        idioma = "en",     -- pt / en / es (padrão: inglês)
        atrasoMs = 80,     -- milissegundos por letra
        enter = true,      -- aperta Enter depois da palavra (mude para false se não precisar)
        letra = "A",       -- letra inicial da rodada
        auto = true,       -- true = tenta detectar a letra sozinho
        trocaAuto = true,  -- true = se acabarem as palavras de um idioma, usa os outros
        pularPrimeira = true, -- true = não digita a 1ª letra (o jogo já preenche a letra da rodada)
        priorizarFinais = true,       -- true = prefere palavras que terminam em letras difíceis
        finaisDificeis = "XZ",        -- RAGE: terminar nessas letras dá ao próximo jogador um prefixo difícil (só letra solta)
        maxPrefixo = 3,               -- máximo de letras iniciais que o jogo pode dar (1, 2 ou 3)
        restaurarTeclado = true,      -- depois de digitar, dá um toque no painel para o teclado do jogo voltar
        nivelVocab = 5,               -- 1 comum | 2 grande | 3 +plurais | 4 ultra | 5 MEGA (padrão). Muda no botão VOCAB
        faisca = true,                -- true = prioriza palavras com 10+ letras (pet Fogos de Artifício). Padrão: ligada
        faiscaMin = 10,               -- quantas letras contam como "palavra longa" para a faísca
        festaAuto = false,            -- botão FESTA: quando armado, digita prefixos sozinho quando o jogo pedir
        festaPalavras = { "prefixo" },-- textos (minúsculos, sem acento) que mostram que o jogo está pedindo prefixo
        festaTextoMax = 80,           -- ignora textos longos (descrição de pet, dicas)
        festaEspera = 0.25,           -- espera antes de digitar, depois que o jogo pede o prefixo (segundos)
        festaReenvio = 4,             -- se o pedido continuar na tela por tanto tempo depois do envio, o jogo recusou: digita outro prefixo
        festaMax = 10,                -- prefixos por Festa
        festaTimeout = 300,           -- desarma sozinho se o jogo não pedir prefixo por esse tempo (segundos)
        autoJogo = false,             -- botão AUTO: joga rodada por rodada sozinho
        autoVezPalavras = { "sua vez", "your turn", "tu turno" }, -- textos (minúsculos, sem acento) que mostram que é a SUA vez. Use DIAG na sua vez e ajuste
        autoErroPalavras = { "invalid", "invalida", "nao existe", "not a word", "ja foi", "already", "no existe", "errad", "wrong", "incorrect" }, -- textos que mostram palavra recusada
        autoEspera = 1.4,             -- segundos esperando o jogo aceitar ou recusar a palavra
        autoTentativas = 3,           -- máximo de palavras digitadas por vez (cada recusa custa vida, então poucas)
        autoPausaErro = 0.8,          -- segundos de pausa depois de apagar uma palavra recusada, antes da próxima
        escalaUI = 0.7,               -- tamanho do painel (1 = normal, 0.6 = bem pequeno)
        autoTempoVez = 20,            -- tempo máximo (segundos) tentando na mesma vez
        autoMaxErros = 5,             -- vezes seguidas sem acertar até o AUTO desligar sozinho
        autoApagarErro = true,        -- apaga o que o script digitou quando o jogo recusa a palavra
        autoIntervalo = 0.15,         -- de quanto em quanto tempo (segundos) confere se é a sua vez
        autoEstavel = 0.15,           -- a letra detectada precisa ficar igual por esse tempo antes de digitar
        autoEsperaVez = 2.0,          -- com a vez aprendida: segundos esperando a vez passar (se não passar, a palavra foi recusada)
        autoErroImplicito = true,     -- true = se a vez não passou depois da palavra, conta como recusada
        autoCego = 5,                 -- segundos sem ver sinal de vez até digitar a cada letra nova (modo às cegas)
        autoArquivoVez = "autotyper_vez.json", -- onde guarda o que o APRENDER descobriu (se o executor permitir)
        autoReenvio = 4,              -- às cegas: segundos até aceitar a mesma letra de novo
        disfarce = false,             -- botão DISFARÇAR: ritmo variado e, às vezes, uma tecla vizinha corrigida na hora (digitação com cara de normal)
        disfarceErro = 0.3,           -- chance de uma palavra ter uma tecla vizinha trocada e corrigida (0 a 1)
        disfarceVar = 0.35,           -- variação do ritmo entre as teclas (0.35 = mais ou menos 35%)
        autoCacar = true,             -- AUTO prefere palavras que TERMINAM no que o oponente tem dificuldade (ex.: "ly")
        dificeisOponente = { "cy", "ly", "z", "x", "zy", "by", "ky" }, -- base: CY > LY > Z > X > ZY > BY > demais; o AUTO pode subir alvos que o oponente demonstrar dificuldade
        usadasMinutos = 20,           -- uma palavra usada fica "usada" por esse tempo (uma partida dura menos que isso)
        usadasReciclar = 180,         -- se acabarem as palavras de um prefixo, só libera as usadas há mais de tantos segundos
        autoUsadaPalavras = { "ja foi", "ja usada", "already", "ya fue", "ya usada" }, -- textos de "palavra já usada" (a palavra é válida: não vai para as recusadas)
        autoSoLista = true,          -- false = aprende nesta partida quais prefixos fazem o oponente demorar e coloca os mais difíceis no topo
        alvoSoSeguras = true,         -- true = os alvos (X, Z, LY) só usam palavras das camadas seguras (sem MEGA); sem palavra segura, joga uma normal
        autoDificilSeg = 5,           -- mínimo de segundos para contar como "demorou" (o AUTO também compara com o ritmo normal do oponente)
        autoDificilFator = 1.7,       -- demorou = mais que isso vezes o tempo normal do oponente
        autoDificilMin = 2,           -- pontos para o AUTO aprender um prefixo (demorou = 1 ponto; demora enorme, provável perda de vida = 2)
        bomba = false,             -- true = prioriza palavras com letras consecutivas (pet Bomba / Mítico)
        bombaModo = "alfabeto",    -- "alfabeto" = letras seguidas no alfabeto (AB, BC, DE, ST...) | "duplas" = letras repetidas (SS, RR, LL...)
        bombaReverso = true,       -- true = conta também ordem reversa (BA, CB, ED, TS...)
        bombaAlvo = 30,            -- pilhas necessárias para a Bomba explodir
        bombaRapido = true,        -- true = escolhe a MENOR palavra válida (digita mais rápido = pilha mais rápido)
    }
    local PASSO_MS, MIN_MS, MAX_MS = 10, 10, 500
    local ALFABETO = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"

    ---------------------------------------------------------------- palavras
    -- Pacotes de palavras: texto separado por espaço, já sem acento (o jogo ignora acentos).
    -- comuns = dia a dia | extras = vocabulário grande | plurais = formas derivadas | ultra = palavras raras e verbais
