    local textos = {
        pt = { escrever = "ESCREVER", aguardando = "Aguardando...", letra = "Letra", lento = "Lento",
               rapido = "Rápido", escrevendo = "Escrevendo...", pronto = "Pronto", sem = "Sem palavra" },
        en = { escrever = "WRITE", aguardando = "Waiting...", letra = "Letter", lento = "Slow",
               rapido = "Fast", escrevendo = "Writing...", pronto = "Done", sem = "No word" },
        es = { escrever = "ESCRIBIR", aguardando = "Esperando...", letra = "Letra", lento = "Lento",
               rapido = "Rápido", escrevendo = "Escribiendo...", pronto = "Listo", sem = "Sin palabra" },
    }

    -- Agrupa as palavras de cada idioma e camada pela letra inicial
    local CAMADAS = { "comuns", "extras", "plurais", "ultra", "longas", "alvos", "mega", "longas2" }
    local NOMES_NIVEL = { "COMUM", "GRANDE", "+PLURAIS", "ULTRA", "MEGA" }
    local bancos = {}
    for idioma, camadasTexto in pairs(pacotes) do
        bancos[idioma] = {}
        for _, camada in ipairs(CAMADAS) do
            bancos[idioma][camada] = {}
            for palavra in (camadasTexto[camada] or ""):gmatch("%S+") do
                local p = palavra:upper()
                local l = p:sub(1, 1)
                bancos[idioma][camada][l] = bancos[idioma][camada][l] or {}
                table.insert(bancos[idioma][camada][l], p)
            end
        end
    end

    -- Prefixos de 3 letras para a Festa do pet: poucas palavras (difícil), mas que EXISTEM no idioma do jogo.
    -- Só vale o idioma escolhido e só as camadas seguras (sem MEGA). O prefixo precisa ter pelo menos uma palavra
    -- comum (COMUNS/EXTRAS); senão o jogo pode recusar e a Festa "pula" a rodada. Os de 1 palavra vêm primeiro.
    local cachePrefixos = {}
    local function listaPrefixos()
        local cod = config.idioma
        if cachePrefixos[cod] then return cachePrefixos[cod] end
        local seguras, comuns = {}, {}
        for camada, porLetra in pairs(bancos[cod]) do
            if camada ~= "mega" then
                for _, lista in pairs(porLetra) do
                    for _, p in ipairs(lista) do
                        if #p >= 4 then
                            local pre = p:sub(1, 3)
                            seguras[pre] = (seguras[pre] or 0) + 1
                            if camada == "comuns" or camada == "extras" then comuns[pre] = (comuns[pre] or 0) + 1 end
                        end
                    end
                end
            end
        end
        local function montar(maxPalavras, exigirComum)
            local grupos = {}
            for n = 1, maxPalavras do grupos[n] = {} end
            for pre, n in pairs(seguras) do
                if n <= maxPalavras and (comuns[pre] or not exigirComum) and pre:match("^%a%a%a$") then
                    table.insert(grupos[n], pre)
                end
            end
            local resultado = {}
            for _, g in ipairs(grupos) do
                table.sort(g)
                for k = #g, 2, -1 do -- embaralha dentro de cada grupo
                    local r = math.random(k)
                    g[k], g[r] = g[r], g[k]
                end
                for _, pre in ipairs(g) do table.insert(resultado, pre) end
            end
            return resultado
        end
        local resultado = montar(3, true)
        if #resultado == 0 then resultado = montar(6, false) end -- idioma com pouco vocabulário
        cachePrefixos[cod] = resultado
        return resultado
    end

