    ---------------------------------------------------------------- botão de minimizar (móvel)
    local COR_ABERTO, COR_FECHADO = roxo, cinza
    local btnMin = novo("TextButton", {
        Name = "Minimizar", Text = "AT", Size = UDim2.fromOffset(44, 44),
        Position = UDim2.new(1, -(210 * config.escalaUI) - 16 - 52, 0, 40), BackgroundColor3 = COR_ABERTO,
        TextColor3 = Color3.new(1, 1, 1), Font = Enum.Font.GothamBold, TextSize = 15,
        AutoButtonColor = false, BorderSizePixel = 0, Active = true,
    }, gui)
    novo("UICorner", { CornerRadius = UDim.new(1, 0) }, btnMin)

    local function alternarPainel()
        painel.Visible = not painel.Visible
        btnMin.BackgroundColor3 = painel.Visible and COR_ABERTO or COR_FECHADO
    end

    -- Toque curto = mostrar/esconder. Arrastar (mais de 6 px) = mover o botão sem alternar.
    local arrastando, moveu, toqueInicial, posInicial = false, false, nil, nil
    btnMin.InputBegan:Connect(function(entrada)
        if entrada.UserInputType == Enum.UserInputType.MouseButton1
            or entrada.UserInputType == Enum.UserInputType.Touch then
            arrastando, moveu = true, false
            toqueInicial, posInicial = entrada.Position, btnMin.Position
            entrada.Changed:Connect(function()
                if entrada.UserInputState == Enum.UserInputState.End then
                    arrastando = false
                    if not moveu then alternarPainel() end
                end
            end)
        end
    end)
    UIS.InputChanged:Connect(function(entrada)
        if arrastando and (entrada.UserInputType == Enum.UserInputType.MouseMovement
            or entrada.UserInputType == Enum.UserInputType.Touch) then
            local delta = entrada.Position - toqueInicial
            if delta.Magnitude > 6 then moveu = true end
            if moveu then
                btnMin.Position = UDim2.new(
                    posInicial.X.Scale, posInicial.X.Offset + delta.X,
                    posInicial.Y.Scale, posInicial.Y.Offset + delta.Y
                )
            end
        end
    end)

    ---------------------------------------------------------------- lógica
    local sugestao = nil
    local sugestaoIdioma = nil
    local sugestaoCamada = nil
    -- palavra (MAIÚSCULA) -> hora em que foi usada. Fica guardada entre execuções do script e vale por usadasMinutos.
    local usadas = genv.AutoTyperUsadas or {}
    genv.AutoTyperUsadas = usadas
    local recusadas = {} -- palavras que o jogo recusou: nunca são sugeridas de novo (não zera com usadas)
    -- Lembra as recusas entre partidas: uma palavra recusada 2 vezes (em qualquer partida) nunca mais é sugerida.
    local ARQ_RECUSADAS = "autotyper_recusadas.txt"
    local contaRecusas = {}
    local metaRecusa = {} -- palavra -> "camada alvo" (só para você poder ler o arquivo)
    pcall(function()
        if not (readfile and isfile and isfile(ARQ_RECUSADAS)) then return end
        for linha in readfile(ARQ_RECUSADAS):gmatch("[^\n]+") do
            local palavra, n, meta = linha:match("^(%a+)%s+(%d+)%s*(.*)$")
            if palavra then
                contaRecusas[palavra] = tonumber(n)
                metaRecusa[palavra] = meta
                if tonumber(n) >= 2 then recusadas[palavra] = true end
            end
        end
    end)
    local function registrarRecusa(palavra, camada, alvo)
        contaRecusas[palavra] = (contaRecusas[palavra] or 0) + 1
        metaRecusa[palavra] = (camada or "?") .. " " .. (alvo or "-")
        if not writefile then return end
        pcall(function()
            local linhas = {}
            for p, n in pairs(contaRecusas) do linhas[#linhas + 1] = p .. " " .. n .. " " .. (metaRecusa[p] or "") end
            writefile(ARQ_RECUSADAS, table.concat(linhas, "\n"))
        end)
    end

    -- Pet BOMBA (Mítico): cada palavra com letras consecutivas = +1 pilha. 30 pilhas = explosão (dano em área).
    local pilhasBomba = 0
    local function temConsecutivas(palavra)
        local str = palavra:upper()
        for i = 1, #str - 1 do
            local a, b = str:byte(i), str:byte(i + 1)
            if config.bombaModo == "duplas" then
                if a == b then return true end                       -- SS, RR, LL, MM...
            else
                if b - a == 1 then return true end                   -- AB, BC, CD, DE...
                if config.bombaReverso and a - b == 1 then return true end -- BA, CB, DC, ED...
            end
        end
        return false
    end

    local function t() return textos[config.idioma] end

    local function atualizarTextos()
        local tx = t()
        btnEscrever.Text = tx.escrever
        btnLento.Text = tx.lento
        btnRapido.Text = tx.rapido
        rMs.Text = config.atrasoMs .. " ms"
        rLetra.Text = string.format("%s: %s (%s)", tx.letra, config.letra, config.auto and "auto" or "manual")
        if sugestao then
            local extra = ""
            if sugestaoIdioma and sugestaoIdioma ~= config.idioma then
                extra = " [" .. sugestaoIdioma:upper() .. "]"
            end
            rPalavra.Text = sugestao .. extra
        else
            rPalavra.Text = tx.sem
        end
        btnRage.Text = config.priorizarFinais and "RAGE: ON" or "RAGE: OFF"
        ligar(btnRage, config.priorizarFinais)
        btnVocab.Text = "VOCAB: " .. NOMES_NIVEL[config.nivelVocab]
        btnFaisca.Text = config.faisca and "FAÍSCA: ON" or "FAÍSCA: OFF"
        ligar(btnFaisca, config.faisca)
        btnFesta.Text = config.festaAuto and "FESTA: ARMADA" or "FESTA: OFF"
        ligar(btnFesta, config.festaAuto)
        btnBomba.Text = config.bomba and ("BOMBA: ON (" .. pilhasBomba .. "/" .. config.bombaAlvo .. ")") or "BOMBA: OFF"
        ligar(btnBomba, config.bomba)
        btnAuto.Text = config.autoJogo and "AUTO: ON" or "AUTO: OFF"
        ligar(btnAuto, config.autoJogo, VERMELHO)
        btnDisfarce.Text = config.disfarce and "DISFARÇAR: ON" or "DISFARÇAR: OFF"
        ligar(btnDisfarce, config.disfarce)
        if sugestao then
            rPalavra.TextColor3 = (config.bomba and temConsecutivas(sugestao)) and Color3.fromRGB(216, 180, 254) or Color3.new(1, 1, 1)
        end
        for cod, b in pairs(botoesIdioma) do
            ligar(b, cod == config.idioma)
        end
    end

    local function terminaDificil(palavra)
        return config.finaisDificeis:find(palavra:sub(-1), 1, true) ~= nil
    end

    -- A palavra precisa começar com TODAS as letras iniciais da rodada e ser maior que elas
    local function combinaPrefixo(palavra)
        return #palavra > #config.letra and palavra:sub(1, #config.letra) == config.letra
    end

    -- Cache: palavras de cada idioma/camada que combinam com o prefixo atual.
    -- A varredura acontece uma vez por prefixo (as listas não mudam), então prefixos
    -- raros como "LY" deixam de travar o jogo a cada sorteio.
    local cachePrefixo = {}
    local function listaDoPrefixo(cod, camada)
        local chave = cod .. "|" .. camada .. "|" .. config.letra
        local c = cachePrefixo[chave]
        if c then return c end
        c = {}
        local lista = bancos[cod][camada][config.letra:sub(1, 1)]
        if lista then
            for _, p in ipairs(lista) do
                if combinaPrefixo(p) then c[#c + 1] = p end
            end
        end
        cachePrefixo[chave] = c
        return c
    end

    -- Dificuldade do oponente: terminar a SUA palavra nessas letras dá a ele um prefixo difícil (ex.: "ly").
    -- O AUTO combina: o que o oponente DESTA partida mostrou sofrer, a sua lista dificeisOponente e o histórico
    -- guardado em autotyper_oponente.txt. "Sofrer" = demorar bem mais que o ritmo normal dele naquele prefixo
    -- (demorou = 1 ponto; demora enorme, provável perda de vida = 2 pontos).
    local ARQ_OPONENTE = "autotyper_oponente.txt"
    local dificuldade = {}              -- histórico: prefixo -> pontos (fica no arquivo)
    local dificuldadeSessao = {}        -- só esta partida: prefixo -> pontos
    local duracoes = {}                 -- tempos "normais" do oponente (o ritmo dele)
    local regraFim = { ok = 0, no = 0 } -- o prefixo dele vem do final da SUA palavra?
    local alvoInutil = false            -- true = a regra acima falhou: caçar terminação não adianta e fica desligado
    local ultimaPalavraAceita = nil
    pcall(function()
        if not (readfile and isfile and isfile(ARQ_OPONENTE)) then return end
        for linha in readfile(ARQ_OPONENTE):gmatch("[^\n]+") do
            local p, n = linha:match("^(%a+)%s+(%d+)$")
            if p then dificuldade[p:lower()] = math.min(tonumber(n), 20) end
        end
    end)

    local function alvosDificeis()
        if alvoInutil then return {} end
        if config.autoSoLista then -- só a sua lista, na ordem dela
            local fixa, vista = {}, {}
            for _, p in ipairs(config.dificeisOponente) do
                local limpo = (tostring(p):lower():gsub("[^a-z]", ""))
                if #limpo > 0 and not vista[limpo] then
                    vista[limpo] = true
                    fixa[#fixa + 1] = limpo
                end
            end
            return fixa
        end
        local lista, visto = {}, {}
        local function add(p)
            if p and #p > 0 and not visto[p] then
                visto[p] = true
                lista[#lista + 1] = p
            end
        end
        local function ordenados(tabela, minimo)
            local ps = {}
            for p, n in pairs(tabela) do
                if n >= minimo then ps[#ps + 1] = p end
            end
            table.sort(ps, function(a, b)
                if tabela[a] ~= tabela[b] then return tabela[a] > tabela[b] end
                return a < b
            end)
            return ps
        end
        -- 1) evidência forte do oponente desta partida
        for _, p in ipairs(ordenados(dificuldadeSessao, config.autoDificilMin + 1)) do add(p) end
        -- 2) a sua lista, na ordem
        for _, p in ipairs(config.dificeisOponente) do add((tostring(p):lower():gsub("[^a-z]", ""))) end
        -- 3) evidência fraca desta partida, depois o histórico
        for _, p in ipairs(ordenados(dificuldadeSessao, config.autoDificilMin)) do add(p) end
        for _, p in ipairs(ordenados(dificuldade, config.autoDificilMin)) do add(p) end
        return lista
    end

    local function alvoDaPalavra(palavra) -- qual alvo a palavra atinge (ou nil)
        local maius = palavra:upper()
        for _, a in ipairs(alvosDificeis()) do
            local alvo = a:upper()
            if #maius > #alvo and maius:sub(-#alvo) == alvo then return a end
        end
        return nil
    end

    -- Compara quanto o oponente demorou com o ritmo normal dele. Devolve 0 (normal), 1 (demorou) ou 2 (demora enorme).
    local function pesoDaDemora(demorou)
        local base = nil
        if #duracoes >= 4 then
            local copia = {}
            for i, v in ipairs(duracoes) do copia[i] = v end
            table.sort(copia)
            base = copia[math.ceil(#copia / 2)] -- mediana
        end
        local limite = config.autoDificilSeg
        if base then limite = math.max(limite, base * config.autoDificilFator) end
        local peso = 0
        if demorou >= limite then
            peso = 1
            if demorou >= math.max(limite * 1.5, base and base * 2.2 or 0) then peso = 2 end
        else
            -- só os tempos normais entram no ritmo, senão o "normal" sobe junto com as demoras
            table.insert(duracoes, demorou)
            if #duracoes > 12 then table.remove(duracoes, 1) end
        end
        return peso
    end

    local function registrarDificuldade(prefixo, peso)
        if #prefixo < 1 or #prefixo > config.maxPrefixo then return end
        local antes = dificuldadeSessao[prefixo] or 0
        dificuldadeSessao[prefixo] = antes + peso
        dificuldade[prefixo] = math.min((dificuldade[prefixo] or 0) + peso, 20)
        if writefile then
            pcall(function()
                local linhas = {}
                for p, n in pairs(dificuldade) do linhas[#linhas + 1] = p .. " " .. n end
                writefile(ARQ_OPONENTE, table.concat(linhas, "\n"))
            end)
        end
        if antes < config.autoDificilMin and dificuldadeSessao[prefixo] >= config.autoDificilMin then
            rStatus.Text = "AUTO: oponente sofre com '" .. prefixo .. "', vou terminar palavras assim"
        end
    end

    -- Confere a ideia central: o prefixo que o oponente recebe vem do FINAL da sua palavra?
    -- Se na maioria das vezes não vem, caçar terminação não adianta e o AUTO desliga isso e avisa.
    local function verificarRegra(prefixo)
        if not ultimaPalavraAceita then return end
        local fim = ultimaPalavraAceita:lower():sub(-#prefixo)
        ultimaPalavraAceita = nil
        if fim == prefixo then regraFim.ok = regraFim.ok + 1 else regraFim.no = regraFim.no + 1 end
        local total = regraFim.ok + regraFim.no
        if total >= 8 and regraFim.ok / total < 0.5 and not alvoInutil then
            alvoInutil = true
            rStatus.Text = "AUTO: o prefixo do oponente não vem do fim da sua palavra; alvo desligado"
        end
    end

    local camadaRuim = {} -- camadas que o AUTO desligou porque o jogo recusava mais da metade das palavras
    local statCamada = {} -- camada -> { ok = n, erro = n } (só vale enquanto o AUTO está ligado)
    local function camadaLigada(nome)
        if config.autoJogo and camadaRuim[nome] then return false end
        if nome == "longas" then return config.faisca or config.nivelVocab >= 5 end -- palavras de 10+ letras: FAÍSCA ou nível MEGA
        if nome == "alvos" then -- palavras que terminam nos alvos (ly, cy, ky, x, z)
            return (config.autoJogo and config.autoCacar) or config.nivelVocab >= 5
        end
        if nome == "longas2" then return config.faisca end -- palavras longas menos garantidas: só na FAÍSCA e por último
        if nome == "mega" then return config.nivelVocab >= 5 end -- camada MEGA só no nível MEGA
        for i, c in ipairs(CAMADAS) do
            if c == nome then return i <= config.nivelVocab end
        end
        return false
    end

    -- Listas já filtradas por prefixo + regra (terminação-alvo, faísca, rage): calculadas UMA vez e guardadas.
    -- Antes cada sorteio refazia essas contas palavra por palavra (milhares de textos novos na memória),
    -- o que enchia a memória de lixo e fazia o jogo travar depois de um tempo.
    local cacheFiltro = {}
    local function listaFiltrada(cod, camada, chave, pred)
        local k = cod .. "|" .. camada .. "|" .. config.letra .. "|" .. chave
        local c = cacheFiltro[k]
        if c then return c end
        c = {}
        for _, p in ipairs(listaDoPrefixo(cod, camada)) do
            if pred(p) then c[#c + 1] = p end
        end
        cacheFiltro[k] = c
        return c
    end

    -- Sorteia uma palavra não usada que comece com o prefixo atual.
    -- As etapas vão da mais forte para a mais fraca e só passa para a próxima se não achar nada.
    -- Em cada etapa vai das palavras comuns para as extras (camadas); no AUTO termina o seu idioma antes
    -- de olhar outro. Se todas as palavras do prefixo já foram usadas, só libera as usadas há mais de
    -- usadasReciclar segundos (nunca zera a partida toda).
    local function sortear()
        local idiomas = { config.idioma }
        if config.trocaAuto then
            for _, cod in ipairs({ "pt", "en", "es" }) do
                if cod ~= config.idioma then table.insert(idiomas, cod) end
            end
        end
        -- palavras usadas há muito tempo deixam de contar
        local agora0 = os.clock()
        for p, t in pairs(usadas) do
            if type(t) ~= "number" or agora0 - t > config.usadasMinutos * 60 then usadas[p] = nil end
        end
        local ORDEM = {}
        for i, c in ipairs(CAMADAS) do ORDEM[c] = i end
        local limitePorEtapa = {} -- etapa -> última camada permitida (os alvos evitam a MEGA)
        local chavePorEtapa = {}  -- etapa -> nome da regra, quando a lista filtrada pode ser guardada
        local etapas = {}
        local alvosMaius = {}
        if config.autoJogo and config.autoCacar then
            for _, a in ipairs(alvosDificeis()) do alvosMaius[#alvosMaius + 1] = a:upper() end
        end
        local limiteAlvo = config.alvoSoSeguras and (ORDEM["mega"] - 1) or nil
        local function addAlvo(a, longa)
            local function termina(p) return #p > #a and p:sub(-#a) == a end
            if longa then
                table.insert(etapas, function(p) return #p >= config.faiscaMin and termina(p) end)
                chavePorEtapa[#etapas] = "alvoF:" .. a
            else
                table.insert(etapas, termina)
                chavePorEtapa[#etapas] = "alvo:" .. a
            end
            limitePorEtapa[#etapas] = limiteAlvo
        end
        if config.faisca then
            -- FAÍSCA ATIVA: palavra longa vem SEMPRE antes de qualquer palavra curta.
            if config.bomba then
                table.insert(etapas, function(p) return #p >= config.faiscaMin and temConsecutivas(p) end)
            end
            for _, a in ipairs(alvosMaius) do addAlvo(a, true) end
            if config.priorizarFinais then
                table.insert(etapas, function(p) return #p >= config.faiscaMin and terminaDificil(p) end)
                chavePorEtapa[#etapas] = "faiscaRage:" .. config.finaisDificeis
            end
            table.insert(etapas, function(p) return #p >= config.faiscaMin end)
            chavePorEtapa[#etapas] = "faisca"
            -- sem palavra com faiscaMin letras para esse prefixo? desce aos poucos (as maiores primeiro)
            for _, minimo in ipairs({ config.faiscaMin - 2, config.faiscaMin - 4 }) do
                if minimo > 4 then
                    table.insert(etapas, function(p) return #p >= minimo end)
                    chavePorEtapa[#etapas] = "len" .. minimo
                end
            end
        end
        if config.bomba then table.insert(etapas, temConsecutivas) end -- palavra que dá pilha na Bomba
        for _, a in ipairs(alvosMaius) do addAlvo(a, false) end
        if config.priorizarFinais then
            table.insert(etapas, terminaDificil)
            chavePorEtapa[#etapas] = "rage:" .. config.finaisDificeis
        end
        table.insert(etapas, function() return true end)

        for _ = 1, 2 do
            local candidatas = 0
            for n, aceita in ipairs(etapas) do
                local ultima = (n == #etapas)
                -- AUTO: palavra de outro idioma é quase certeza de erro (perde vida), então as etapas de preferência
                -- só olham o SEU idioma. Os outros idiomas só entram na última etapa, se faltar palavra.
                local idiomasEtapa = idiomas
                if config.autoJogo and not ultima then idiomasEtapa = { idiomas[1] } end
                local limite = limitePorEtapa[n]
                local chave = chavePorEtapa[n]
                local ehBomba = config.bomba and config.bombaRapido and aceita == temConsecutivas

                local function tentar(cod, camada)
                    if not camadaLigada(camada) then return nil end
                    if limite and ORDEM[camada] > limite then return nil end
                    local lista
                    if chave then lista = listaFiltrada(cod, camada, chave, aceita) else lista = listaDoPrefixo(cod, camada) end
                    local total = #lista
                    if total == 0 then return nil end
                    if ultima then candidatas = candidatas + total end
                    -- lista grande: tenta algumas palavras ao acaso antes de olhar uma por uma
                    if total > 64 and not ehBomba then
                        for _ = 1, 48 do
                            local p = lista[math.random(total)]
                            if not usadas[p] and not recusadas[p] and (chave or aceita(p)) then return p end
                        end
                    end
                    local livres = {}
                    for _, p in ipairs(lista) do
                        if not usadas[p] and not recusadas[p] and (chave or aceita(p)) then table.insert(livres, p) end
                    end
                    if #livres == 0 then return nil end
                    if ehBomba then
                        table.sort(livres, function(a, b) return #a < #b end)
                        return livres[1] -- menor palavra válida = digita mais rápido
                    end
                    return livres[math.random(#livres)]
                end

                if config.autoJogo then
                    -- AUTO: termina o seu idioma em todas as camadas antes de olhar outro idioma
                    for _, cod in ipairs(idiomasEtapa) do
                        for _, camada in ipairs(CAMADAS) do
                            local p = tentar(cod, camada)
                            if p then return p, cod, camada end
                        end
                    end
                else
                    for _, camada in ipairs(CAMADAS) do
                        for _, cod in ipairs(idiomasEtapa) do
                            local p = tentar(cod, camada)
                            if p then return p, cod, camada end
                        end
                    end
                end
            end
            if candidatas == 0 then return nil, nil end
            -- tudo usado: libera só o que foi usado há mais de usadasReciclar segundos
            local agora = os.clock()
            local liberou = false
            for p, t in pairs(usadas) do
                if agora - t > config.usadasReciclar then
                    usadas[p] = nil
                    liberou = true
                end
            end
            if not liberou then return nil, nil end
        end
        return nil, nil
    end

    local function novaSugestao()
        sugestao, sugestaoIdioma, sugestaoCamada = sortear()
        atualizarTextos()
    end

    local function definirLetra(l)
        local mudou = (l ~= config.letra)
        config.letra = l
        if mudou or not sugestao or usadas[sugestao] or not combinaPrefixo(sugestao) then
            novaSugestao()
        else
            atualizarTextos()
        end
    end

    local function visivel(obj)
        local atual = obj
        while atual do
            if atual:IsA("GuiObject") and not atual.Visible then return false end
            if (atual:IsA("ScreenGui") or atual:IsA("BillboardGui") or atual:IsA("SurfaceGui")) and not atual.Enabled then
                return false
            end
            atual = atual.Parent
        end
        return true
    end

    -- Palpite: junta os "tiles" de letras visíveis em linhas (por GUI e por altura),
    -- vota na letra inicial mais comum e usa a MENOR linha que começa com ela como
    -- prefixo (o jogo pode dar 1, 2 ou 3 letras iniciais). Se a linha for maior que
    -- maxPrefixo (provavelmente uma palavra inteira), usa só a primeira letra.
    local function raizDoGui(obj)
        local atual = obj
        while atual do
            if atual:IsA("LayerCollector") then return atual end
            atual = atual.Parent
        end
        return workspace
    end

    local function detectarLetra(soGui)
        local porRaiz = {}
        local function considerar(obj)
            if #obj.Text == 1 and obj.Text:match("^%u$") and not obj:IsDescendantOf(gui) and visivel(obj) then
                local r = raizDoGui(obj)
                porRaiz[r] = porRaiz[r] or {}
                table.insert(porRaiz[r], {
                    x = obj.AbsolutePosition.X,
                    y = obj.AbsolutePosition.Y,
                    letra = obj.Text,
                })
            end
        end
        for obj in pairs(textLabels) do considerar(obj) end -- registro vivo: sem varrer o PlayerGui inteiro
        if not soGui and os.clock() - ultimoScanWorkspace >= 4 then
            ultimoScanWorkspace = os.clock()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("TextLabel") then considerar(obj) end
            end
        end

        local linhas = {} -- cada item é uma linha de tiles lida da esquerda para a direita
        for _, tiles in pairs(porRaiz) do
            table.sort(tiles, function(a1, b1) return a1.y < b1.y end)
            local atual, refY = {}, nil
            local function fechar()
                if #atual > 0 then
                    table.sort(atual, function(a1, b1) return a1.x < b1.x end)
                    local letras = {}
                    for _, tile in ipairs(atual) do table.insert(letras, tile.letra) end
                    local s = table.concat(letras)
                    -- ignora a fileira de "X" vermelhos (tentativas erradas): não é letra da rodada
                    if not (#s >= 2 and s:match("^X+$")) then
                        table.insert(linhas, s)
                    end
                end
                atual = {}
            end
            for _, tile in ipairs(tiles) do
                if refY and tile.y - refY > 6 then
                    fechar()
                    refY = nil
                end
                refY = refY or tile.y
                table.insert(atual, tile)
            end
            fechar()
        end

        -- palavras completas que já estão na tela (as dos outros jogadores) contam como usadas
        for _, s in ipairs(linhas) do
            if #s >= 4 and #s > config.maxPrefixo then usadas[s] = os.clock() end
        end

        local votos, melhor, max = {}, nil, 0
        for _, s in ipairs(linhas) do
            local l = s:sub(1, 1)
            votos[l] = (votos[l] or 0) + 1
            if votos[l] > max then
                max = votos[l]
                melhor = l
            end
        end
        if not melhor then return nil end

        local menor = nil
        for _, s in ipairs(linhas) do
            if s:sub(1, 1) == melhor and (not menor or #s < #menor) then menor = s end
        end
        if menor and #menor <= config.maxPrefixo then return menor end
        return melhor
    end

    local function pressionar(tecla)
        if not okVIM then return end
        pcall(function()
            VIM:SendKeyEvent(true, tecla, false, game)
            task.wait(0.01)
            VIM:SendKeyEvent(false, tecla, false, game)
        end)
    end

    local digitadas = 0 -- quantas letras o script digitou na última palavra

    -- Os toques/teclas simulados fazem alguns jogos esconderem o teclado da tela
    -- (acham que você está num teclado físico). Um toque no título do painel avisa
    -- que a entrada voltou a ser touch. É um toque em lugar inofensivo.
    local function restaurarTeclado()
        if not config.restaurarTeclado or not okVIM or not painel.Visible then return end
        pcall(function()
            local inset = GuiService:GetGuiInset()
            local centro = titulo.AbsolutePosition + titulo.AbsoluteSize / 2
            VIM:SendTouchEvent(1, 0, centro.X, centro.Y + inset.Y)
            task.wait(0.03)
            VIM:SendTouchEvent(1, 2, centro.X, centro.Y + inset.Y)
        end)
    end

    local function apagar(n)
        for _ = 1, n do
            pressionar(Enum.KeyCode.Backspace)
            task.wait(0.03)
        end
    end

    -- DISFARÇAR: teclas vizinhas no teclado (QWERTY) para trocar de leve e corrigir, e ritmo que varia.
    local VIZINHAS = {
        Q = "WA", W = "QES", E = "WRD", R = "ETF", T = "RYG", Y = "TUH", U = "YIJ", I = "UOK", O = "IPL", P = "OL",
        A = "QSZ", S = "ADWX", D = "SFEC", F = "DGRV", G = "FHTB", H = "GJYN", J = "HKUM", K = "JLIM", L = "KOP",
        Z = "XA", X = "ZCS", C = "XVD", V = "CBF", B = "VNG", N = "BMH", M = "NJK",
    }
    local function pausaTecla(base)
        if not config.disfarce then task.wait(base) return end
        local fator = 1 + (math.random() * 2 - 1) * config.disfarceVar
        local espera = math.max(0.02, base * fator)
        if math.random() < 0.07 then espera = espera + 0.08 + math.random() * 0.15 end -- uma hesitada de vez em quando
        task.wait(espera)
    end

    -- semErro = true: sem tecla trocada (usado nas tentativas seguintes, quando o tempo está curto)
    local function digitar(palavra, semErro)
        digitadas = 0
        local inicio = config.pularPrimeira and (#config.letra + 1) or 1
        local base = config.atrasoMs / 1000
        local function tecla(c)
            pressionar(Enum.KeyCode[c])
            digitadas = digitadas + 1
            pausaTecla(base)
        end
        -- no máximo uma tecla trocada por palavra, nunca na primeira nem na última letra digitada
        local posErro = nil
        if config.disfarce and not semErro and (#palavra - inicio) >= 4 and math.random() < config.disfarceErro then
            posErro = math.random(inicio + 1, #palavra - 1)
        end
        if config.disfarce then task.wait(math.random() * 0.15) end -- não começa no mesmo milissegundo
        local k = inicio
        while k <= #palavra do
            local c = palavra:sub(k, k)
            if c:match("%a") then
                if k == posErro and VIZINHAS[c] then
                    posErro = nil
                    local viz = VIZINHAS[c]
                    local n = math.random(#viz)
                    tecla(viz:sub(n, n)) -- tecla vizinha no lugar da certa
                    local extra = 0
                    local c2 = palavra:sub(k + 1, k + 1)
                    if math.random() < 0.4 and c2:match("%a") then -- às vezes só percebe uma letra depois
                        tecla(c2)
                        extra = 1
                    end
                    task.wait(0.1 + math.random() * 0.2) -- o "ops"
                    apagar(1 + extra)
                    digitadas = digitadas - (1 + extra)
                    tecla(c)
                    if extra == 1 then
                        tecla(c2)
                        k = k + 1
                    end
                else
                    tecla(c)
                end
            else
                pausaTecla(base)
            end
            k = k + 1
        end
        if config.disfarce then task.wait(0.05 + math.random() * 0.12) end
        if config.enter then pressionar(Enum.KeyCode.Return) end
        restaurarTeclado()
    end

    local escrevendo = false
    btnEscrever.MouseButton1Click:Connect(function()
        if escrevendo then return end
        escrevendo = true
        task.spawn(function()
            if config.auto then
                local l = detectarLetra()
                if l then definirLetra(l) end
            end
            if not sugestao then novaSugestao() end
            if sugestao then
                local palavra = sugestao
                rStatus.Text = t().escrevendo
                digitar(palavra)
                usadas[palavra] = os.clock()
                if config.bomba then
                    if temConsecutivas(palavra) then
                        pilhasBomba = pilhasBomba + 1
                        if pilhasBomba >= config.bombaAlvo then
                            rStatus.Text = "BOMBA: " .. pilhasBomba .. "/" .. config.bombaAlvo .. " EXPLODIU!"
                            pilhasBomba = 0 -- zera e recomeça para a próxima explosão
                        else
                            rStatus.Text = "Bomba: +1 pilha (" .. pilhasBomba .. "/" .. config.bombaAlvo .. ")"
                        end
                    else
                        rStatus.Text = "Bomba: " .. pilhasBomba .. "/" .. config.bombaAlvo .. " (sem letras consecutivas)"
                    end
                else
                    rStatus.Text = t().pronto
                end
                novaSugestao()
            else
                rStatus.Text = t().sem
            end
            escrevendo = false
        end)
    end)

    for cod, b in pairs(botoesIdioma) do
        b.MouseButton1Click:Connect(function()
            config.idioma = cod
            novaSugestao()
            rStatus.Text = t().aguardando
        end)
    end

    local function moverLetra(d)
        local i = ALFABETO:find(config.letra:sub(1, 1), 1, true) or 1
        i = (i - 1 + d) % 26 + 1
        config.auto = false
        definirLetra(ALFABETO:sub(i, i))
    end
    btnAnt.MouseButton1Click:Connect(function() moverLetra(-1) end)
    btnProx.MouseButton1Click:Connect(function() moverLetra(1) end)
    rLetra.MouseButton1Click:Connect(function()
        config.auto = not config.auto
        atualizarTextos()
    end)

    btnLento.MouseButton1Click:Connect(function()
        config.atrasoMs = math.min(MAX_MS, config.atrasoMs + PASSO_MS)
        atualizarTextos()
    end)
    btnRapido.MouseButton1Click:Connect(function()
        config.atrasoMs = math.max(MIN_MS, config.atrasoMs - PASSO_MS)
        atualizarTextos()
    end)

    btnRage.MouseButton1Click:Connect(function()
        config.priorizarFinais = not config.priorizarFinais
        novaSugestao()
    end)

    btnVocab.MouseButton1Click:Connect(function()
        config.nivelVocab = config.nivelVocab % #NOMES_NIVEL + 1
        novaSugestao()
    end)

    btnApagar.MouseButton1Click:Connect(function()
        task.spawn(function()
            apagar(1)
            digitadas = math.max(0, digitadas - 1)
        end)
    end)
    btnLimpar.MouseButton1Click:Connect(function()
        task.spawn(function()
            apagar(digitadas) -- apaga só o que o script digitou; as letras iniciais do jogo ficam
            digitadas = 0
            rStatus.Text = t().aguardando
        end)
    end)
    btnEnter.MouseButton1Click:Connect(function()
        task.spawn(function() pressionar(Enum.KeyCode.Return) end)
    end)

    btnFaisca.MouseButton1Click:Connect(function()
        config.faisca = not config.faisca
        novaSugestao()
    end)

    -- PREFIXO: digita o próximo prefixo difícil de 3 letras (Festa: até 10 por vez)
    local idxPrefixo, usosFesta = 0, 0
    local function digitarProximoPrefixo()
        local lista = listaPrefixos()
        if #lista == 0 then return end
        idxPrefixo = idxPrefixo % #lista + 1
        usosFesta = usosFesta % config.festaMax + 1
        local pre = lista[idxPrefixo]
        rStatus.Text = "Prefixo: " .. pre .. " (" .. usosFesta .. "/" .. config.festaMax .. ")"
        digitadas = 0
        for i = 1, #pre do
            pressionar(Enum.KeyCode[pre:sub(i, i)])
            digitadas = digitadas + 1
            task.wait(config.atrasoMs / 1000)
        end
        if config.enter then pressionar(Enum.KeyCode.Return) end
        restaurarTeclado()
    end

    btnPrefixo.MouseButton1Click:Connect(function()
        if escrevendo or #listaPrefixos() == 0 then return end
        escrevendo = true
        task.spawn(function()
            digitarProximoPrefixo()
            escrevendo = false
        end)
    end)

    -- FESTA automática: arme o botão quando estiver perto da Festa. A partida segue rodada a rodada:
    -- cada vez que o jogo pedir um prefixo (texto curto com "prefixo", veja festaPalavras) ele digita
    -- UM prefixo, espera o pedido sumir (fim da rodada) e só então espera o próximo pedido, até
    -- festaMax vezes. Se nada aparecer por festaTimeout segundos, desarma sozinho.
    local function simples(s)
        local mapa = { ["á"] = "a", ["à"] = "a", ["â"] = "a", ["ã"] = "a", ["é"] = "e", ["ê"] = "e",
                       ["í"] = "i", ["ó"] = "o", ["ô"] = "o", ["õ"] = "o", ["ú"] = "u", ["ç"] = "c" }
        return (s:lower():gsub(utf8.charpattern, function(c) return mapa[c] or c end))
    end

    -- Guarda o texto que pede o prefixo: enquanto ele estiver na tela, conferir é barato (não varre tudo de novo).
    local festaCache = nil
    local function textoDaFesta()
        local c = festaCache
        if c and c.Parent and c:IsDescendantOf(playerGui) and c.Text ~= "" and visivel(c) then
            local txt = simples(c.Text)
            for _, palavra in ipairs(config.festaPalavras) do
                if txt:find(palavra, 1, true) then return c.Text end
            end
        end
        festaCache = nil
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Text ~= ""
                and #obj.Text <= config.festaTextoMax and not obj:IsDescendantOf(gui) and visivel(obj) then
                local txt = simples(obj.Text)
                for _, palavra in ipairs(config.festaPalavras) do
                    if txt:find(palavra, 1, true) then
                        festaCache = obj
                        return obj.Text
                    end
                end
            end
        end
        return nil
    end

    -- Um prefixo por pedido. A rodada conta como concluída quando o pedido some depois do envio. Se o pedido
    -- continuar na tela festaReenvio segundos depois do envio, o jogo recusou: digita OUTRO prefixo (não pula).
    local festaRodando = false
    local function rodarFesta()
        if festaRodando then return end
        festaRodando = true
        task.spawn(function()
            local enviados, ultimoVisto = 0, os.clock()
            local jaEnviou, ultimoEnvio = false, 0
            rStatus.Text = "Festa: esperando o jogo pedir..."
            while config.festaAuto and vivo() and enviados < config.festaMax do
                local agora = os.clock()
                if textoDaFesta() then
                    ultimoVisto = agora
                    if jaEnviou and agora - ultimoEnvio > config.festaReenvio then jaEnviou = false end
                    if not jaEnviou and not escrevendo and #listaPrefixos() > 0 then
                        task.wait(config.festaEspera)
                        escrevendo = true
                        digitarProximoPrefixo()
                        escrevendo = false
                        jaEnviou, ultimoEnvio = true, os.clock()
                    end
                else
                    if jaEnviou then -- o pedido sumiu depois do envio: rodada concluída
                        enviados = enviados + 1
                        jaEnviou = false
                        rStatus.Text = "Festa: " .. enviados .. "/" .. config.festaMax .. " (esperando a próxima rodada)"
                    end
                    if agora - ultimoVisto > config.festaTimeout then
                        rStatus.Text = "Festa: tempo esgotado"
                        break
                    end
                end
                task.wait(festaCache and 0.12 or 0.3)
            end
            if enviados >= config.festaMax then rStatus.Text = "Festa: concluída (" .. enviados .. "/" .. config.festaMax .. ")" end
            config.festaAuto = false
            festaRodando = false
            atualizarTextos()
        end)
    end

    btnFesta.MouseButton1Click:Connect(function()
        config.festaAuto = not config.festaAuto
        if config.festaAuto then rodarFesta() end
        atualizarTextos()
    end)

    -- DIAG: copia para a área de transferência todos os textos visíveis na tela (use durante a Festa)
    btnDiag.MouseButton1Click:Connect(function()
        local linhas = {}
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Text ~= ""
                and not obj:IsDescendantOf(gui) and visivel(obj) then
                table.insert(linhas, string.format('[%s] %s | "%s"', obj.ClassName, obj:GetFullName(), obj.Text:sub(1, 80)))
            end
        end
        local texto = table.concat(linhas, "\n")
        if setclipboard then
            setclipboard(texto)
            rStatus.Text = "DIAG copiado (" .. #linhas .. " textos)"
        else
            print(texto)
            rStatus.Text = "DIAG no console (F9)"
        end
    end)

    btnBomba.MouseButton1Click:Connect(function()
        config.bomba = not config.bomba
        if config.bomba then pilhasBomba = 0 end -- começa a contagem do zero
        novaSugestao()
    end)


    ---------------------------------------------------------------- AUTO: joga rodada por rodada
    -- Lê a tela a cada autoIntervalo segundos. Quando é a sua vez, detecta o prefixo e digita uma palavra.
    -- Depois espera autoEspera segundos: se o jogo recusar (texto de erro novo ou mais "X" na tela), apaga,
    -- marca a palavra como recusada e tenta outra, subindo uma escada de degraus:
    --   1 outra palavra | 2 FAÍSCA invertida | 3 vocabulário +1 | 4 vocabulário MEGA + FAÍSCA invertida
    --   5 MEGA + 2º idioma | 6 MEGA + 3º idioma. Ao fim da vez, volta tudo para as suas configurações.
    local autoRodando = false
    local autoViuVez = false -- o texto da sua vez já apareceu alguma vez?
    local placar = { ok = 0, erro = 0 }

    -- Aprende com os resultados: se uma camada (PLURAIS, ULTRA, MEGA ou as palavras longas da FAÍSCA) for recusada
    -- em mais de 35% das tentativas (mínimo 5), o AUTO para de usá-la até você desligar e ligar o AUTO de novo.
    -- COMUNS e EXTRAS nunca são desligadas, para sempre sobrar palavra.
    local function registrarResultado(camada, aceitou)
        if not camada then return end
        local st = statCamada[camada]
        if not st then
            st = { ok = 0, erro = 0 }
            statCamada[camada] = st
        end
        if aceitou then st.ok = st.ok + 1 else st.erro = st.erro + 1 end
        local total = st.ok + st.erro
        local minimo, taxa = 5, 0.35
        if camada == "longas" then minimo, taxa = 8, 0.5 end -- a faísca depende dela: mais tolerante
        if camada ~= "comuns" and camada ~= "extras" and total >= minimo and st.erro / total > taxa
            and not camadaRuim[camada] then
            camadaRuim[camada] = true
            rStatus.Text = "AUTO: desliguei a camada " .. camada:upper() .. " (muitos erros)"
        end
    end

    local function lerSinais()
        local sinais = { vez = false, erro = false, usada = false, x = 0 }
        for _, obj in ipairs(playerGui:GetDescendants()) do
            local ehLabel = obj:IsA("TextLabel")
            if (ehLabel or obj:IsA("TextButton")) and obj.Text ~= "" and not obj:IsDescendantOf(gui) then
                local texto = obj.Text
                if ehLabel and texto == "X" then
                    local cor = obj.TextColor3
                    if cor.R > 0.6 and cor.G < 0.45 and cor.B < 0.45 and visivel(obj) then
                        sinais.x = sinais.x + 1 -- "X" vermelho = tentativa errada
                    end
                elseif #texto <= config.festaTextoMax then
                    local txt = simples(texto)
                    if not sinais.vez then
                        for _, p in ipairs(config.autoVezPalavras) do
                            if txt:find(p, 1, true) and visivel(obj) then sinais.vez = true break end
                        end
                    end
                    if not sinais.erro then
                        for _, p in ipairs(config.autoErroPalavras) do
                            if txt:find(p, 1, true) and visivel(obj) then sinais.erro = true break end
                        end
                    end
                    if not sinais.usada then
                        for _, p in ipairs(config.autoUsadaPalavras) do
                            if txt:find(p, 1, true) and visivel(obj) then
                                sinais.usada, sinais.erro = true, true -- "já usada" também é uma recusa
                                break
                            end
                        end
                    end
                end
            end
        end
        return sinais
    end

    ---------------------------------------------------------------- APRENDER a sua vez
    -- Sem saber como o jogo mostra "é a sua vez", o AUTO aprende comparando duas fotos da tela:
    -- uma na vez do OPONENTE e outra na SUA vez. O que só aparece na sua vez vira o sinal.
    -- Depois disso, conferir a vez é só olhar esses objetos (rápido, sem varrer a tela toda).
    local HttpService = game:GetService("HttpService")
    local aprendido = { minha = {}, outro = {} } -- itens { nome = caminho dentro do PlayerGui, obj = objeto }
    local fotoOutro = nil
    local ultimaResolucao = 0
    local prefixoGui = playerGui:GetFullName() .. "."

    local function nomeRel(obj)
        return obj:GetFullName():sub(#prefixoGui + 1)
    end

    local function fotografar()
        local foto = {}
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if obj:IsA("GuiObject") and visivel(obj) then
                foto[nomeRel(obj)] = obj
            end
        end
        return foto
    end

    -- 3 fotos em 0,4 s: fica só o que aparece em todas (tira animações e avisos passageiros)
    local function fotoEstavel()
        local base = fotografar()
        for _ = 1, 2 do
            task.wait(0.2)
            local outra = fotografar()
            for nome in pairs(base) do
                if not outra[nome] then base[nome] = nil end
            end
        end
        return base
    end

    local function diferenca(fotoMinha, fotoOutra)
        local lista = {}
        for nome, obj in pairs(fotoMinha) do
            if not fotoOutra[nome] then lista[#lista + 1] = { nome = nome, obj = obj } end
        end
        table.sort(lista, function(a, b) return a.nome < b.nome end)
        while #lista > 25 do table.remove(lista) end
        return lista
    end

    -- procura de novo os objetos pelo caminho (quando o jogo recria a interface a cada vez)
    local function reresolver()
        ultimaResolucao = os.clock()
        local procurados = {}
        for _, item in ipairs(aprendido.minha) do procurados[item.nome] = item end
        for _, item in ipairs(aprendido.outro) do procurados[item.nome] = item end
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if obj:IsA("GuiObject") then
                local item = procurados[nomeRel(obj)]
                if item then item.obj = obj end
            end
        end
    end

    -- true = é a sua vez | false = não é | nil = ainda não aprendeu
    local function minhaVezAprendida()
        local lista = aprendido.minha
        local total = #lista
        if total == 0 then return nil end
        local vivos, visiveis = 0, 0
        for _, item in ipairs(lista) do
            local obj = item.obj
            if obj and obj.Parent and obj:IsDescendantOf(playerGui) then
                vivos = vivos + 1
                if visivel(obj) then visiveis = visiveis + 1 end
            end
        end
        if vivos < total * 0.5 and os.clock() - ultimaResolucao > 0.4 then reresolver() end
        return visiveis >= math.max(1, math.ceil(total * 0.6))
    end

    -- vez aprendida > texto de vez (autoVezPalavras) > nil (não sei)
    local function vezAtiva()
        local aprendida = minhaVezAprendida()
        if aprendida ~= nil and autoViuVez then return aprendida end -- aprendida velha (nunca vista) não vale
        if #config.autoVezPalavras > 0 and autoViuVez then return lerSinais().vez end
        return nil
    end

    local function salvarAprendizado()
        if not writefile then return end
        pcall(function()
            local dados = { minha = {}, outro = {} }
            for _, item in ipairs(aprendido.minha) do dados.minha[#dados.minha + 1] = item.nome end
            for _, item in ipairs(aprendido.outro) do dados.outro[#dados.outro + 1] = item.nome end
            writefile(config.autoArquivoVez, HttpService:JSONEncode(dados))
        end)
    end

    local function carregarAprendizado()
        if not (readfile and isfile) then return end
        pcall(function()
            if not isfile(config.autoArquivoVez) then return end
            local dados = HttpService:JSONDecode(readfile(config.autoArquivoVez))
            for _, nome in ipairs(dados.minha or {}) do table.insert(aprendido.minha, { nome = nome }) end
            for _, nome in ipairs(dados.outro or {}) do table.insert(aprendido.outro, { nome = nome }) end
        end)
    end
    carregarAprendizado()
    btnAprender.Text = #aprendido.minha > 0 and "VEZ OK" or "APRENDER"

    -- Escada de tentativas depois de uma recusa. Cada recusa custa vida, então os degraus começam pelas
    -- palavras mais comuns (mais chance de o jogo aceitar) e só depois abrem o vocabulário todo:
    --   1 GRANDE | 2 ULTRA | 3 MEGA | 4 MEGA com FAÍSCA invertida. Nos degraus 1+ RAGE e a troca de idioma ficam desligados.
    local function aplicarDegrau(n, base)
        config.faisca, config.nivelVocab, config.idioma = base.faisca, base.nivel, base.idioma
        config.priorizarFinais, config.trocaAuto = base.rage, base.troca
        if n < 1 then return end
        local maximo = #NOMES_NIVEL
        config.faisca, config.priorizarFinais, config.trocaAuto = false, false, false
        if n == 1 then
            config.nivelVocab = 2
        elseif n == 2 then
            config.nivelVocab = 4
        elseif n == 3 then
            config.nivelVocab = maximo
        else
            config.nivelVocab = maximo
            config.faisca = not base.faisca
        end
    end

    -- apaga devagar e espera o jogo "assentar" antes da próxima palavra (apagar rápido demais deixa letras sobrando)
    local function apagarSeguro(n)
        for _ = 1, n do
            pressionar(Enum.KeyCode.Backspace)
            task.wait(0.07)
        end
        task.wait(config.autoPausaErro)
    end

    -- depois de digitar: "erro" se o jogo recusou, "ok" se aceitou.
    -- Com a vez aprendida: a vez passou = aceitou; a vez continua depois de autoEsperaVez = recusou.
    local function esperarVeredito(antes)
        local aprendida = #aprendido.minha > 0 and autoViuVez
        local limite = os.clock() + (aprendida and config.autoEsperaVez or config.autoEspera)
        local conheceVez = #config.autoVezPalavras > 0 and autoViuVez
        local passo = 0
        while os.clock() < limite and config.autoJogo do
            task.wait(0.1)
            passo = passo + 1
            if aprendida and not minhaVezAprendida() then return "ok" end
            if passo % 3 == 0 then
                local agora = lerSinais()
                if (agora.erro and not antes.erro) or agora.x > antes.x then return "erro", agora.usada end
                if not aprendida and conheceVez and antes.vez and not agora.vez then return "ok" end
            end
        end
        if aprendida and config.autoErroImplicito and minhaVezAprendida() then return "erro" end
        return "ok"
    end

    local function contarBomba(palavra)
        if config.bomba and temConsecutivas(palavra) then
            pilhasBomba = pilhasBomba + 1
            if pilhasBomba >= config.bombaAlvo then pilhasBomba = 0 end
        end
    end

    -- uma vez completa: tenta palavras até o jogo aceitar (no máximo autoTentativas digitadas). Devolve true se aceitou.
    local function jogarVez()
        local base = { faisca = config.faisca, nivel = config.nivelVocab, idioma = config.idioma,
                       rage = config.priorizarFinais, troca = config.trocaAuto }
        local inicio = os.clock()
        local aceitou, digitou = false, 0
        ultimaPalavraAceita = nil
        for degrau = 0, 4 do
            if not config.autoJogo or digitou >= config.autoTentativas
                or os.clock() - inicio > config.autoTempoVez then break end
            aplicarDegrau(degrau, base)
            novaSugestao()
            local palavra = sugestao
            local camada = sugestaoCamada
            if palavra then -- sem palavra neste degrau: passa para o próximo sem digitar nada
                digitou = digitou + 1
                local antes = lerSinais()
                rStatus.Text = "AUTO: " .. palavra .. (digitou > 1 and (" (tentativa " .. digitou .. ")") or "")
                digitar(palavra, digitou > 1)
                usadas[palavra] = os.clock()
                local veredito, foiUsada = esperarVeredito(antes)
                if not foiUsada then registrarResultado(camada, veredito ~= "erro") end
                if veredito == "erro" then
                    placar.erro = placar.erro + 1
                    if foiUsada then
                        -- a palavra é válida, só já tinha sido usada: fica nas usadas (já está) e não vai para as recusadas
                        rStatus.Text = "AUTO: " .. palavra .. " já tinha sido usada, apagando..."
                    else
                        recusadas[palavra] = true
                        registrarRecusa(palavra, camada, alvoDaPalavra(palavra))
                        rStatus.Text = "AUTO: recusou " .. palavra .. ", apagando..."
                    end
                    if config.autoApagarErro then
                        apagarSeguro(digitadas)
                        digitadas = 0
                    else
                        task.wait(config.autoPausaErro)
                    end
                    -- a vez acabou (o jogo recusou e passou para outro)? então para de tentar
                    if vezAtiva() == false then break end
                else
                    aceitou = true
                    ultimaPalavraAceita = palavra
                    contarBomba(palavra)
                    placar.ok = placar.ok + 1
                    local alvo = config.autoCacar and alvoDaPalavra(palavra)
                    rStatus.Text = "AUTO: " .. palavra .. " OK (" .. placar.ok .. " ok, " .. placar.erro .. " erro)"
                        .. (alvo and (" [alvo " .. alvo .. "]") or "")
                    break
                end
            end
        end
        config.faisca, config.nivelVocab, config.idioma = base.faisca, base.nivel, base.idioma
        config.priorizarFinais, config.trocaAuto = base.rage, base.troca
        novaSugestao()
        return aceitou
    end

    local function rodarAuto()
        if autoRodando then return end
        autoRodando = true
        task.spawn(function()
            local jaJogou, ultimaLetra, ultimoJogo = false, nil, 0
            local errosSeguidos, inicioAuto, ciclos = 0, os.clock(), 0
            local letraVista, letraDesde, sinaisCache = nil, 0, nil
            local oppPrefixo, oppDesde = nil, 0 -- prefixo em que o oponente está e desde quando
            autoViuVez = false
            if #aprendido.minha > 0 then
                rStatus.Text = "AUTO: esperando sua vez..."
            else
                rStatus.Text = "AUTO: toque APRENDER para ele saber a sua vez"
            end
            if config.autoCacar then
                local alvos = alvosDificeis()
                if #alvos > 0 then rStatus.Text = rStatus.Text .. " | alvo: " .. table.concat(alvos, ", ") end
            end
            while config.autoJogo and vivo() do
                task.wait(config.autoIntervalo)
                if not escrevendo then
                    local ok, erro = pcall(function()
                        ciclos = ciclos + 1
                        local vez = minhaVezAprendida() -- true / false / nil (ainda não aprendeu)
                        if vez == nil and #config.autoVezPalavras > 0 then
                            if ciclos % 3 == 1 or not sinaisCache then sinaisCache = lerSinais() end
                            vez = sinaisCache.vez
                        end
                        if vez then autoViuVez = true end
                        local temSinal = (vez ~= nil)
                        -- sem sinal de vez (ou ele nunca apareceu): trabalha "às cegas", a cada letra nova
                        local cego = (not temSinal) or (not autoViuVez and os.clock() - inicioAuto > config.autoCego)
                        if temSinal and not vez then jaJogou = false end

                        -- aprende com o oponente: quanto ele demora em cada prefixo, comparado com o ritmo normal dele
                        if config.autoCacar and temSinal then
                            if vez then
                                if oppPrefixo then
                                    local demorou = os.clock() - oppDesde
                                    if demorou <= 90 then
                                        local peso = pesoDaDemora(demorou)
                                        if peso > 0 then registrarDificuldade(oppPrefixo, peso) end
                                    end
                                    oppPrefixo = nil
                                end
                            elseif not oppPrefixo and ciclos % 4 == 0 then
                                local p = detectarLetra(true)
                                if p then
                                    p = p:lower()
                                    -- logo depois da sua jogada a tela ainda pode mostrar o SEU prefixo: ignora
                                    local velho = ultimaLetra ~= nil and p == ultimaLetra:lower() and os.clock() - ultimoJogo < 1.5
                                    if not velho then
                                        -- só vale o PRIMEIRO prefixo da vez dele (a troca de letra depois de perder vida não conta)
                                        oppPrefixo = p
                                        oppDesde = (os.clock() - ultimoJogo < 4) and ultimoJogo or os.clock()
                                        verificarRegra(p)
                                    end
                                end
                            end
                        end

                        local escanear
                        if cego then
                            escanear = (ciclos % 3 == 0)
                        else
                            escanear = vez and (not jaJogou or ciclos % 6 == 0)
                        end
                        if not escanear then return end

                        local letra = detectarLetra(true)
                        if not letra and ciclos % 3 == 0 then letra = detectarLetra(false) end
                        if not letra then
                            letraVista = nil
                            return
                        end
                        if letra ~= letraVista then letraVista, letraDesde = letra, os.clock() end
                        local agora = os.clock()
                        local pode
                        if cego then
                            pode = (letra ~= ultimaLetra) or (agora - ultimoJogo > config.autoReenvio)
                        else
                            pode = (not jaJogou) or (letra ~= ultimaLetra and agora - ultimoJogo > 3)
                        end
                        -- a letra precisa ficar igual um instante: o jogo às vezes mostra a letra velha antes da nova
                        if not (pode and agora - letraDesde >= config.autoEstavel) then return end

                        definirLetra(letra)
                        escrevendo = true
                        local acertou = jogarVez()
                        escrevendo = false
                        jaJogou, ultimaLetra, ultimoJogo, letraVista = true, letra, os.clock(), nil
                        if acertou then
                            errosSeguidos = 0
                        else
                            errosSeguidos = errosSeguidos + 1
                            if errosSeguidos >= config.autoMaxErros then
                                config.autoJogo = false
                                rStatus.Text = "AUTO: desligado (" .. errosSeguidos .. " vezes sem acertar)"
                            else
                                rStatus.Text = "AUTO: sem palavra aceita, esperando..."
                            end
                        end
                        atualizarTextos()
                    end)
                    if not ok then
                        escrevendo = false
                        warn("AUTO erro: ", erro)
                    end
                end
            end
            autoRodando = false
            atualizarTextos()
        end)
    end

    -- APRENDER: toque 1 na vez do OPONENTE, toque 2 na SUA vez (a letra de prefixo já tem que estar na tela)
    local aprendendo = 0 -- 0 parado | 1 esperando a foto da sua vez | 2 tirando foto
    btnAprender.MouseButton1Click:Connect(function()
        if aprendendo == 2 then return end
        task.spawn(function()
            if aprendendo == 0 then
                aprendendo = 2
                rStatus.Text = "Aprender: foto da vez do OPONENTE..."
                fotoOutro = fotoEstavel()
                aprendendo = 1
                btnAprender.Text = "AGORA"
                rStatus.Text = "Agora toque de novo na SUA vez"
            else
                aprendendo = 2
                rStatus.Text = "Aprender: foto da SUA vez..."
                local lista = diferenca(fotoEstavel(), fotoOutro)
                if #lista == 0 then
                    rStatus.Text = "Aprender: nada mudou. Tente de novo"
                else
                    aprendido.minha, aprendido.outro = lista, {}
                    salvarAprendizado()
                    rStatus.Text = "Aprendi a sua vez (" .. #lista .. " sinais)"
                end
                fotoOutro = nil
                aprendendo = 0
                btnAprender.Text = #aprendido.minha > 0 and "VEZ OK" or "APRENDER"
            end
        end)
    end)

    btnDisfarce.MouseButton1Click:Connect(function()
        config.disfarce = not config.disfarce
        atualizarTextos()
    end)

    btnAuto.MouseButton1Click:Connect(function()
        config.autoJogo = not config.autoJogo
        if config.autoJogo then
            config.festaAuto = false -- Festa e Auto digitam as duas: só uma por vez
            for k in pairs(camadaRuim) do camadaRuim[k] = nil end
            statCamada = {}
            placar.ok, placar.erro = 0, 0
            dificuldadeSessao, duracoes, regraFim, alvoInutil = {}, {}, { ok = 0, no = 0 }, false
            rodarAuto()
        else
            rStatus.Text = "AUTO: desligado"
        end
        atualizarTextos()
    end)

    novaSugestao()
    rStatus.Text = t().aguardando
end)

if not sucesso then
    warn("Erro ao executar o script / Script error / Error al ejecutar el script: ", erro)
end
